import sys
from collections import defaultdict

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    t = int(sys.stdin.readline().strip())
    results = []

    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        tree = defaultdict(list)
        for _ in range(n - 1):
            p, a, b = read_ints()
            tree[p].append((_, a, b))
            tree[p].append((_, a, b))

        # Calculate the cumulative sum of a_j values for each node
        cum_sum_a = [0] * n
        for i in range(1, n):
            for j, a, b in tree[i]:
                cum_sum_a[j] = cum_sum_a[i] + a

        # Find the maximum prefix for each node
        r = [0] * n
        for i in range(2, n + 1):
            current_sum_a = cum_sum_a[i - 1]
            for j in range(i):
                if cum_sum_a[j] <= current_sum_a:
                    r[i - 1] = j
                else:
                    break

        results.append(' '.join(map(str, r[1:])))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
